package warranty

import (
	"errors"
	"testing"
)

// 本文件回归保障取消功能在同一备件被多笔承诺共同占用时的行为：取消一笔只
// 释放这笔承诺自身的未用数量，已使用的部分不回补实物库存，其他请求或同一
// 请求的其他有效承诺一律不受影响；释放出的可承诺数量随后可以被新的合格请求
// 全部预留，且对已取消承诺的重复取消与新使用都不能再次改变库存。

// cancelSharedStore 构造一个保修 60 天的产品、初始库存 12 件的备件和三个
// 保修资格请求（请求甲 rA、请求乙 rB、取消后新到的请求 rC）。
func cancelSharedStore(t *testing.T) *Store {
	t.Helper()
	s := NewStore()
	if err := s.RegisterProduct("p1", t0, 60, nil); err != nil {
		t.Fatalf("register product: %v", err)
	}
	if err := s.RegisterPart("part1", 12); err != nil {
		t.Fatalf("register part: %v", err)
	}
	for _, id := range []string{"rA", "rB", "rC"} {
		if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
			t.Fatalf("submit request %s: %v", id, err)
		}
	}
	return s
}

// mustDetailByID 在承诺明细列表中按编号查找，找不到时失败。
func mustDetailByID(t *testing.T, details []CommitmentDetail, commitID string) CommitmentDetail {
	t.Helper()
	for _, d := range details {
		if d.CommitmentID == commitID {
			return d
		}
	}
	t.Fatalf("commitment %q not found in details %+v", commitID, details)
	return CommitmentDetail{}
}

// assertPartAccount 断言备件账目三项数值与调用方可见的库存规则一致：
// 实物剩余只扣成功使用量，有效占用只计有效承诺的未用数量。
func assertPartAccount(t *testing.T, s *Store, physical, occupied, committable int) {
	t.Helper()
	st, err := s.PartStatus("part1", nowOK)
	if err != nil {
		t.Fatalf("part status: %v", err)
	}
	if st.PhysicalRemaining != physical || st.ActiveOccupied != occupied || st.Committable != committable {
		t.Fatalf("stock account: phys=%d occupied=%d committable=%d, want phys=%d occupied=%d committable=%d",
			st.PhysicalRemaining, st.ActiveOccupied, st.Committable, physical, occupied, committable)
	}
}

// TestCancelReleasesOnlyThisCommitmentUnused 以同一备件初始库存 12 件为例：
// 请求甲两笔承诺分别预留 5 件和 2 件，请求乙一笔承诺预留 4 件。从甲的 5 件
// 承诺使用 2 件后取消该承诺，只能释放其未用的 3 件；取消记录仍可追查但不再
// 计入有效占用，甲的另一笔承诺与乙的承诺数量、归属和到期时刻保持原值。
func TestCancelReleasesOnlyThisCommitmentUnused(t *testing.T) {
	s := cancelSharedStore(t)

	// 三笔承诺各给不同的到期时刻（均晚于全部操作时刻），以便回归保障取消
	// 不会篡改其他承诺的到期时刻。
	expA5 := t0.Add(40 * day)
	expA2 := t0.Add(50 * day)
	expB4 := t0.Add(30 * day)

	if _, err := s.Reserve("cA5", "rA", "part1", 5, expA5, nowOK); err != nil {
		t.Fatalf("reserve cA5: %v", err)
	}
	if _, err := s.Reserve("cA2", "rA", "part1", 2, expA2, nowOK); err != nil {
		t.Fatalf("reserve cA2: %v", err)
	}
	if _, err := s.Reserve("cB4", "rB", "part1", 4, expB4, nowOK); err != nil {
		t.Fatalf("reserve cB4: %v", err)
	}

	// 从请求甲的 5 件承诺中使用 2 件：实物 10，有效占用 9（3+2+4），可承诺 1。
	if _, err := s.Use("uA-used", "cA5", 2, nowOK); err != nil {
		t.Fatalf("use 2 from cA5: %v", err)
	}
	assertPartAccount(t, s, 10, 9, 1)

	// 取消这笔 5 件承诺：返回结果仍保留原定 5、已用 2、未用 3，并显示已取消。
	canceled, err := s.Cancel("cA5", nowOK)
	if err != nil {
		t.Fatalf("cancel cA5: %v", err)
	}
	if !canceled.Canceled || canceled.Quantity != 5 || canceled.Used != 2 || canceled.Unused() != 3 {
		t.Fatalf("cancel result: %+v, want qty=5 used=2 unused=3 canceled=true", canceled)
	}

	// 实物仍是 10（已用 2 件不回补），有效占用降为 6（2+4），可承诺变为 4。
	assertPartAccount(t, s, 10, 6, 4)

	// 直接取回的承诺同样保留原定/已用/未用事实并显示已取消。
	got, err := s.Commitment("cA5")
	if err != nil {
		t.Fatalf("commitment cA5: %v", err)
	}
	if !got.Canceled || got.Quantity != 5 || got.Used != 2 || got.Unused() != 3 {
		t.Fatalf("stored canceled commitment: %+v", got)
	}

	// 按请求查看：请求甲仍能看到自己的两笔承诺。
	viewA, err := s.RequestView("rA", nowOK)
	if err != nil {
		t.Fatalf("request view rA: %v", err)
	}
	if len(viewA.Commitments) != 2 {
		t.Fatalf("rA commitments = %d, want 2 (canceled record still visible)", len(viewA.Commitments))
	}
	dA5 := mustDetailByID(t, viewA.Commitments, "cA5")
	if dA5.Status != CommitmentCanceled || dA5.OriginalQuantity != 5 ||
		dA5.UsedQuantity != 2 || dA5.RemainingQuantity != 3 ||
		dA5.RequestID != "rA" || dA5.PartID != "part1" || !dA5.Expiry.Equal(expA5) {
		t.Fatalf("rA view of cA5: %+v", dA5)
	}
	// 甲的另一笔承诺继续有效，数量、归属与到期时刻保持原值。
	dA2 := mustDetailByID(t, viewA.Commitments, "cA2")
	if dA2.Status != CommitmentActive || dA2.OriginalQuantity != 2 ||
		dA2.UsedQuantity != 0 || dA2.RemainingQuantity != 2 ||
		dA2.RequestID != "rA" || !dA2.Expiry.Equal(expA2) {
		t.Fatalf("rA view of cA2 changed after cancel: %+v", dA2)
	}

	// 请求乙只看到自己的承诺：4 件有效，原值不变。
	viewB, err := s.RequestView("rB", nowOK)
	if err != nil {
		t.Fatalf("request view rB: %v", err)
	}
	if len(viewB.Commitments) != 1 {
		t.Fatalf("rB commitments = %d, want 1", len(viewB.Commitments))
	}
	dB4 := mustDetailByID(t, viewB.Commitments, "cB4")
	if dB4.Status != CommitmentActive || dB4.OriginalQuantity != 4 ||
		dB4.UsedQuantity != 0 || dB4.RemainingQuantity != 4 ||
		dB4.RequestID != "rB" || dB4.PartID != "part1" || !dB4.Expiry.Equal(expB4) {
		t.Fatalf("rB view of cB4 changed after other request's cancel: %+v", dB4)
	}

	// 按备件查看：取消记录仍保留在明细中，各笔状态与库存总数一致。
	st, err := s.PartStatus("part1", nowOK)
	if err != nil {
		t.Fatalf("part status: %v", err)
	}
	if len(st.Details) != 3 {
		t.Fatalf("part details = %d, want 3 (canceled record retained)", len(st.Details))
	}
	pdA5 := mustDetailByID(t, st.Details, "cA5")
	if pdA5.Status != CommitmentCanceled || pdA5.OriginalQuantity != 5 ||
		pdA5.UsedQuantity != 2 || pdA5.RemainingQuantity != 3 {
		t.Fatalf("part detail cA5: %+v", pdA5)
	}
	if mustDetailByID(t, st.Details, "cA2").Status != CommitmentActive {
		t.Fatal("part detail cA2 not active")
	}
	if mustDetailByID(t, st.Details, "cB4").Status != CommitmentActive {
		t.Fatal("part detail cB4 not active")
	}
	// 明细中有效承诺的未用数量之和必须等于有效占用，已取消明细不参与。
	activeUnused := 0
	for _, d := range st.Details {
		if d.Status == CommitmentActive {
			activeUnused += d.RemainingQuantity
		}
	}
	if activeUnused != st.ActiveOccupied {
		t.Fatalf("active details unused sum = %d, want ActiveOccupied %d", activeUnused, st.ActiveOccupied)
	}
}

// TestCanceledUnusedCanBeReservedThenCancelStaysInert 取消释放出的 4 件可
// 承诺数量随后被一个有保修资格的新请求全部预留；此后再次取消原承诺不能二次
// 释放，原承诺上的新使用返回 ErrCommitmentClosed，其他请求已取得的占用不受
// 影响。
func TestCanceledUnusedCanBeReservedThenCancelStaysInert(t *testing.T) {
	s := cancelSharedStore(t)

	if _, err := s.Reserve("cA5", "rA", "part1", 5, t0.Add(40*day), nowOK); err != nil {
		t.Fatalf("reserve cA5: %v", err)
	}
	if _, err := s.Reserve("cA2", "rA", "part1", 2, t0.Add(50*day), nowOK); err != nil {
		t.Fatalf("reserve cA2: %v", err)
	}
	if _, err := s.Reserve("cB4", "rB", "part1", 4, t0.Add(30*day), nowOK); err != nil {
		t.Fatalf("reserve cB4: %v", err)
	}
	if _, err := s.Use("uA-used", "cA5", 2, nowOK); err != nil {
		t.Fatalf("use 2 from cA5: %v", err)
	}
	if _, err := s.Cancel("cA5", nowOK); err != nil {
		t.Fatalf("cancel cA5: %v", err)
	}
	// 取消后：实物 10，有效占用 6，可承诺 4。
	assertPartAccount(t, s, 10, 6, 4)

	// 新请求在晚于取消的操作时刻预留释放后的全部 4 件：成功。
	later := t0.Add(11 * day)
	cC4, err := s.Reserve("cC4", "rC", "part1", 4, t0.Add(35*day), later)
	if err != nil {
		t.Fatalf("reserve freed 4 for rC: %v", err)
	}
	if cC4.Quantity != 4 || cC4.Used != 0 || cC4.RequestID != "rC" || cC4.Canceled || cC4.Expired {
		t.Fatalf("new commitment for rC: %+v", cC4)
	}
	// 实物仍为 10，有效占用变为 10（2+4+4），可承诺为 0。
	st, err := s.PartStatus("part1", later)
	if err != nil {
		t.Fatalf("part status: %v", err)
	}
	if st.PhysicalRemaining != 10 || st.ActiveOccupied != 10 || st.Committable != 0 {
		t.Fatalf("stock after freed quantity re-reserved: phys=%d occupied=%d committable=%d",
			st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
	}
	// 可承诺确认为 0：再要 1 件的新合格请求无法预留。
	if _, err := s.Reserve("cC-extra", "rC", "part1", 1, t0.Add(35*day), later); !errors.Is(err, ErrInsufficientStock) {
		t.Fatalf("reserve beyond zero committable: got %v, want ErrInsufficientStock", err)
	}

	// 再次取消原来的 5 件承诺：正常返回已取消结果，但不能再次释放 3 件。
	again, err := s.Cancel("cA5", later)
	if err != nil {
		t.Fatalf("repeat cancel cA5: %v", err)
	}
	if !again.Canceled || again.Quantity != 5 || again.Used != 2 || again.Unused() != 3 {
		t.Fatalf("repeat cancel result: %+v", again)
	}
	st2, err := s.PartStatus("part1", later)
	if err != nil {
		t.Fatalf("part status after repeat cancel: %v", err)
	}
	if st2.PhysicalRemaining != 10 || st2.ActiveOccupied != 10 || st2.Committable != 0 {
		t.Fatalf("repeat cancel changed stock: phys=%d occupied=%d committable=%d",
			st2.PhysicalRemaining, st2.ActiveOccupied, st2.Committable)
	}

	// 对原承诺用新的使用编号提交 1 件使用：返回 ErrCommitmentClosed。
	if _, err := s.Use("uA-after-cancel", "cA5", 1, later); !errors.Is(err, ErrCommitmentClosed) {
		t.Fatalf("new usage on canceled commitment: got %v, want ErrCommitmentClosed", err)
	}

	// 实物库存与各笔已用数量保持原值。
	st3, err := s.PartStatus("part1", later)
	if err != nil {
		t.Fatalf("part status after rejected usage: %v", err)
	}
	if st3.PhysicalRemaining != 10 || st3.ActiveOccupied != 10 || st3.Committable != 0 {
		t.Fatalf("rejected usage changed stock: phys=%d occupied=%d committable=%d",
			st3.PhysicalRemaining, st3.ActiveOccupied, st3.Committable)
	}
	cA5, _ := s.Commitment("cA5")
	if cA5.Used != 2 || !cA5.Canceled {
		t.Fatalf("cA5 after rejected usage: %+v", cA5)
	}
	for _, tc := range []struct {
		id   string
		want Commitment
	}{
		{"cA2", Commitment{ID: "cA2", RequestID: "rA", PartID: "part1", Quantity: 2, Used: 0}},
		{"cB4", Commitment{ID: "cB4", RequestID: "rB", PartID: "part1", Quantity: 4, Used: 0}},
		{"cC4", Commitment{ID: "cC4", RequestID: "rC", PartID: "part1", Quantity: 4, Used: 0}},
	} {
		c, err := s.Commitment(tc.id)
		if err != nil {
			t.Fatalf("commitment %s: %v", tc.id, err)
		}
		if c.Canceled || c.Expired || c.Quantity != tc.want.Quantity || c.Used != 0 || c.RequestID != tc.want.RequestID {
			t.Fatalf("active commitment %s disturbed: %+v", tc.id, c)
		}
	}
}

package warranty

import (
	"fmt"
	"time"
)

// stockAccountLocked 按统一的库存规则核算指定备件当前的账目：实物剩余只扣除
// 成功使用的数量（即备件当前库存），有效占用是该备件所有未取消、未确认到期
// 承诺的未用总量，可承诺数量等于实物剩余减去有效占用。已取消或已确认到期的
// 承诺不计入占用；到期一经确认不可逆，与本次传入的当前时刻无关，因此这里
// 不接收当前时刻，时刻相关的到期确认由调用方在核算前对本次涉及的承诺显式
// 完成。新预留的库存核算与按备件的库存查询共用这一份账目，同一条库存规则
// 不再分别维护。
//
// 调用方须已确认备件存在。
func (s *Store) stockAccountLocked(partID string) StockBasis {
	account := StockBasis{PhysicalRemaining: s.parts[partID].Stock}
	for _, c := range s.commitments {
		if c.PartID != partID {
			continue
		}
		if c.Canceled || c.Expired {
			continue
		}
		account.ActiveOccupied += c.Unused()
	}
	account.Committable = account.PhysicalRemaining - account.ActiveOccupied
	return account
}

// Reserve 为请求预留一种备件，数量为正整数，到期时刻必须晚于本次提交的当前时刻。
// 每次首次预留都按当次时刻重新判断资格；可承诺数量等于剩余实物库存扣除所有
// 有效承诺的未用数量。库存不足、未知请求或备件、不合格请求都不占用数量。
//
// 新预留的库存核算会先按本次当前时刻确认该备件下已到期的承诺：当前时刻达到
// 其到期时刻的未取消承诺被永久标记到期，只释放未用占用、不增加实物库存；该
// 结果不可逆，之后即使传入更早时刻核算也不再计算其未用数量，不能再次占用已
// 释放给其他请求的数量。空编号、非正数量等参数非法，或请求、备件（含资格所
// 需产品）不存在而提前失败的调用，不用本次时刻确认任何承诺。
//
// 提交编号全局唯一。已成功的编号：
//   - 原样重试（请求编号、备件编号、数量和到期时刻一致；当前时刻不属于提交内容，
//     到期时刻按实际时刻比较，换时区表示仍算一致）只取回首次预留成功的完整承诺，
//     其中已用数量仍为零、取消标记仍为否，不重新判断资格与库存，不重复占用，不
//     追加历史，也不恢复已释放占用或补回已扣减的实物库存；无论请求后来过保、库存
//     不足，还是承诺已分批使用、全部使用、取消或到期，即使本次当前时刻等于或晚于
//     原到期时刻，均如此。
//   - 改请求、备件、数量或到期时刻任一项即返回 ErrConflict，即使新参数本身非法
//     （空请求、未知备件、零数量、已过去的到期时刻）也按编号冲突处理；失败记录挂在
//     本次提交指定的已知请求下，请求为空或不存在时不创建请求和历史。
//
// 首次成功与编号绑定在同一临界区内原子完成：同一个尚未成功预留的编号被两组不同
// 内容（请求、备件、数量或到期时刻不同）并发抢占，且每组内容都可能同时提交多次
// 时，只能有一份内容成为首次承诺——与其完全相同的并发提交全部成功并返回同一份
// 完整首次承诺（已用数量为零、未取消），另一组全部返回 ErrConflict，不能两笔都
// 成功，也不会把后来的内容写进已经成功的承诺；即使库存充足到能同时容纳两笔数量，
// 有效占用也只对应获胜数量（预留不扣减实物库存），承诺只归获胜请求。库存恰好被
// 首次成功预留用完时，同内容的其余并发提交仍取回首次结果而不是 ErrInsufficientStock，
// 另一组仍报编号冲突；赛后按胜出内容重试取回首次承诺，按落败内容重试仍冲突，库存
// 与归属保持原结果。获胜请求只留一条首次成功记录（保存当次资格与新增占用前的库存
// 依据），相同内容的其余成功返回不追加；落败请求的每次提交各留一条冲突失败记录，
// 保留当次数量、到期时刻与当前时刻，资格与库存依据均为空，记录不挂到获胜请求下。
//
// 尚未成功占用的编号继续按本次参数、资格和库存判断；失败记录照常保留，失败后允许
// 用该编号再次提交。每次首次预留成功及每次失败提交都会在对应请求下留下记录。
func (s *Store) Reserve(commitID, requestID, partID string, quantity int, expiry, now time.Time) (Commitment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 本次提交的历史记录骨架：承诺编号、备件、数量、到期时刻与当前时刻在各分支
	// 一致，统一在这里填写，各分支不再重复。record 按统一规则留痕：成功标记与
	// 失败类别互斥，资格与库存依据快照原样保存（提前失败时为 nil，不用合格资格
	// 或零库存替代缺失）；请求为空或尚未登记时不创建请求和历史。
	base := HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
	}
	record := func(success bool, herr HistoryError, elig *Eligibility, basis *StockBasis) {
		rec := base
		rec.Success = success
		rec.Error = herr
		rec.Eligibility = cloneEligibility(elig)
		rec.StockBasis = basis
		s.recordReserveLocked(requestID, rec)
	}

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：原样重试不因本次当前
	// 时刻晚于到期时刻等参数问题失败；改内容则一律冲突。
	if first, ok := s.firstResults[commitID]; ok {
		if first.RequestID != requestID || first.PartID != partID ||
			first.Quantity != quantity || !first.Expiry.Equal(expiry) {
			// 冲突：在本次提交指定的已知请求下记录失败，不挂到原承诺所属请求。
			record(false, HistoryErrorConflict, nil, nil)
			return Commitment{}, fmt.Errorf("%w: commit id %q reused with different content", ErrConflict, commitID)
		}
		// 原样重试：返回首次成功时的承诺快照，不反映后来的使用、取消或到期。
		return first, nil
	}

	if commitID == "" || requestID == "" || partID == "" {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: commit/request/part id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: reserve quantity must be a positive integer", ErrInvalidParam)
	}
	if !expiry.After(now) {
		record(false, HistoryErrorInvalidParam, nil, nil)
		return Commitment{}, fmt.Errorf("%w: expiry must be after current time", ErrInvalidParam)
	}

	req, ok := s.requests[requestID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	if _, ok := s.parts[partID]; !ok {
		record(false, HistoryErrorPartNotFound, nil, nil)
		return Commitment{}, fmt.Errorf("%w: part %q", ErrNotFound, partID)
	}
	elig, err := s.evaluateLocked(req, now)
	if err != nil {
		// 产品未登记：资格依据明确为空，不用合格替代缺失。
		record(false, HistoryErrorProductNotFound, nil, nil)
		return Commitment{}, err
	}

	// 库存核算前先按本次时刻确认该备件已到期的承诺。到期确认不可逆，之后
	// 即使传入更早时刻也不再计入占用。放在参数与引用校验之后：提前失败的
	// 非法或缺失引用调用不确认任何承诺。
	s.confirmPartExpiriesLocked(partID, now)

	// 库存依据：本次提交处理前的实物剩余、有效占用与可承诺数量，与库存
	// 查询共用同一份核算；在新增承诺落库之前取快照，本次新增占用不计入。
	stockBasis := s.stockAccountLocked(partID)

	if !elig.Eligible {
		record(false, HistoryErrorIneligible, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: %v", ErrIneligible, elig.Reasons)
	}

	if quantity > stockBasis.Committable {
		record(false, HistoryErrorInsufficientStock, elig, &stockBasis)
		return Commitment{}, fmt.Errorf("%w: need %d, committable %d", ErrInsufficientStock, quantity, stockBasis.Committable)
	}

	c := &Commitment{
		ID:        commitID,
		RequestID: requestID,
		PartID:    partID,
		Quantity:  quantity,
		Expiry:    expiry,
	}
	// 成功记录、承诺与首次结果快照在同一把锁内同时落库，查询不会看到只占用库存
	// 却没有成功记录的中间状态；快照独立于活动承诺，之后的使用、取消或到期不
	// 会改变原样重试取回的值。
	s.commitments[commitID] = c
	s.firstResults[commitID] = *c
	record(true, "", elig, &stockBasis)
	return *c, nil
}

// Use 使用一笔承诺，数量为正整数，分批扣减该承诺未用数量和剩余实物库存。
// 数量超过未用数量时整次失败，不改变任何记录。
//
// 使用编号全局唯一：相同编号且相同内容的重试返回首次成功结果，不再次扣减，
// 也不借本次时刻确认任何承诺到期；编号一旦已有成功记录，后续提交的承诺编号或
// 数量与首次成功内容不同即返回 ErrConflict——即使新内容本身非法（空承诺编号、
// 指向不存在的承诺、数量为零或负数、超过承诺余量），或新指定的承诺已取消或
// 到期，也一律按编号冲突处理：不扣减实物库存、不改变任何承诺的已用数量、不
// 释放占用，也不借本次时刻确认原承诺或新承诺到期，更不会用新内容覆盖原记录。
// 首次成功与编号绑定在同一临界区内原子完成：多个相同内容的并发提交全部成功并
// 返回同一份完整使用记录，但承诺累计已用数量与实物库存只随首次成功变化一次
// （恰好耗尽余量时其余提交仍取回首次结果，不会被当作新的超量使用）；首次成功
// 前两组不同内容并发抢占同一编号时，只有一份内容成为成功记录，与其相同的提交
// 全部取回该结果，另一组全部 ErrConflict，扣减量只对应胜出内容，落败承诺不变。
// 已经成功的使用在承诺取消或到期后原样重试，仍返回原结果，已确认到期的承诺
// 也不会因此重新开放。新使用（非重试）会按本次当前时刻确认这一笔承诺：已取消
// 或已确认到期，或本次时刻达到其到期时刻的，一律返回 ErrCommitmentClosed；到期
// 一经确认不可逆，之后即使传入更早时刻也仍被拒绝。尚无成功记录的编号按本次
// 参数处理：空编号、空承诺编号、非正数量返回 ErrInvalidParam，引用未知承诺返回
// ErrNotFound，这些提前失败不用本次时刻确认到期，也不占用编号，修正内容后仍可
// 提交。已全部使用的承诺不再接受新使用。
func (s *Store) Use(usageID, commitID string, quantity int, now time.Time) (Usage, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// 已成功的编号优先按重复提交处理，优先于本次参数校验：沿用成功编号但把
	// 承诺编号改成空串或未知承诺、把数量改成零或负数等本身非法的内容，仍属于
	// 对已成功提交内容的改动，按 ErrConflict 处理，与普通非法输入区分。成功
	// 使用的编号必非空，因此空编号不会命中这里，继续走参数校验。
	if existing, ok := s.usages[usageID]; ok {
		if existing.CommitmentID != commitID || existing.Quantity != quantity {
			return Usage{}, fmt.Errorf("%w: usage id %q reused with different content", ErrConflict, usageID)
		}
		return *existing, nil
	}

	if usageID == "" || commitID == "" {
		return Usage{}, fmt.Errorf("%w: usage/commit id must not be empty", ErrInvalidParam)
	}
	if quantity <= 0 {
		return Usage{}, fmt.Errorf("%w: usage quantity must be a positive integer", ErrInvalidParam)
	}

	c, ok := s.commitments[commitID]
	if !ok {
		return Usage{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	// 新使用判断：按本次时刻确认这一笔承诺是否到期。一经确认不可逆，之后
	// 即使传入更早时刻也一律关闭。已取消的承诺不确认到期，仍保持 canceled。
	s.confirmExpiryLocked(c, now)
	if c.Canceled {
		return Usage{}, fmt.Errorf("%w: commitment %q is canceled", ErrCommitmentClosed, commitID)
	}
	if c.Expired {
		return Usage{}, fmt.Errorf("%w: commitment %q expired at %v", ErrCommitmentClosed, commitID, c.Expiry)
	}
	if quantity > c.Quantity-c.Used {
		return Usage{}, fmt.Errorf("%w: need %d, unused %d", ErrUsageExceeded, quantity, c.Quantity-c.Used)
	}

	c.Used += quantity
	s.parts[c.PartID].Stock -= quantity
	u := &Usage{ID: usageID, CommitmentID: commitID, Quantity: quantity}
	s.usages[usageID] = u
	return *u, nil
}

// Cancel 取消承诺，只释放未用数量，不影响已扣减的实物库存。
// 重复取消不增加库存；承诺已到期时余量已自动失效，取消同样不产生变化。
// 取消后的承诺不能继续使用。
func (s *Store) Cancel(commitID string, now time.Time) (Commitment, error) {
	if commitID == "" {
		return Commitment{}, fmt.Errorf("%w: commit id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	c, ok := s.commitments[commitID]
	if !ok {
		return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, commitID)
	}
	if !c.Canceled {
		c.Canceled = true
	}
	return *c, nil
}

