// assertNewCommitmentAbsent 核对失败的新预留不留任何痕迹：承诺不存在，请求
// 丙的视图没有关联承诺，备件明细只有两笔旧记录。
func assertNewCommitmentAbsent(t *testing.T, s *Store) {
